import {esc,fmt} from './offset-exports.js';
export const SCENE_VIEWS={iso:{label:'立體',axes:['run','rise'],matrix:[[.866,-.866,0],[.5,.5,-1]]},front:{label:'正視 XZ',axes:['run','rise'],matrix:[[1,0,0],[0,0,-1]]},top:{label:'俯視 XY',axes:['run','roll'],matrix:[[1,0,0],[0,-1,0]]},side:{label:'側視 YZ',axes:['roll','rise'],matrix:[[0,1,0],[0,0,-1]]}};
export function scenePoint(q,frame){return frame.matrix.map((row,i)=>frame.origin[i]+row.reduce((n,v,k)=>n+v*q[k],0)*frame.scale);}
export function sceneDragDelta(delta,frame){const fields=frame.axes,idx=fields.map(f=>['run','roll','rise'].indexOf(f)),a=frame.matrix[0][idx[0]],b=frame.matrix[0][idx[1]],c=frame.matrix[1][idx[0]],d=frame.matrix[1][idx[1]],det=a*d-b*c;return {[fields[0]]:(d*delta[0]-b*delta[1])/det/frame.scale,[fields[1]]:(a*delta[1]-c*delta[0])/det/frame.scale};}
const axisVec=(p,end)=>{const value=p[end+'Axis'];if(value==='custom'){const v=['X','Y','Z'].map(k=>Number(p[end+'Axis'+k])||0),n=Math.hypot(...v);return n?v.map(x=>x/n):[1,0,0];}const q=[0,0,0],i='xyz'.indexOf(value?.[0]);if(i>=0)q[i]=value[1]==='-'?-1:1;return q;};
const xy=q=>q.map(v=>fmt(v)).join(' ');
export function portScene(p,view='iso',selected=null,fixed=null){
 const info=SCENE_VIEWS[view]??SCENE_VIEWS.iso,q=[p.run,p.layout==='rolling'?p.roll:0,p.rise].map(v=>Number.isFinite(v)?v:0),project=v=>info.matrix.map(row=>row.reduce((n,x,k)=>n+x*v[k],0)),parts=[[0,0,0],[q[0],0,0],[q[0],q[1],0],q],points=parts.map(project),min=[0,1].map(i=>Math.min(...points.map(v=>v[i]))),max=[0,1].map(i=>Math.max(...points.map(v=>v[i]))),scale=Math.min(300/Math.max(max[0]-min[0],200),175/Math.max(max[1]-min[1],200)),frame=fixed??{...info,scale,origin:[130+(300-(max[0]-min[0])*scale)/2-min[0]*scale,65+(175-(max[1]-min[1])*scale)/2-min[1]*scale]},at=v=>scenePoint(v,frame),colors=['#b58039','#378b70','#3b83aa'];
 const dims=parts.slice(1).map((v,i)=>`<path d="M${xy(at(parts[i]))}L${xy(at(v))}" stroke="${colors[i]}" stroke-width="2" stroke-dasharray="5 5" fill="none"/>`).join('');
 const ports=['a','b'].map((end,i)=>{const pos=at(i?q:[0,0,0]),direction=project(axisVec(p,end)),n=Math.hypot(...direction),u=n>1e-6?direction.map(v=>v/n):[1,0],tail=pos.map((v,k)=>v-u[k]*62),endArrow=pos.map((v,k)=>v+u[k]*29),active=selected===end,color=active?'#246d8b':'#688399';return `<g class="scene-port${active?' selected':''}" data-port="${end}" role="button" tabindex="0" aria-label="${end.toUpperCase()} 管口，點選朝向${end==='b'?'；拖曳調整位置':''}"><path d="M${xy(tail)}L${xy(pos)}" stroke="#34576f" stroke-width="30" stroke-linecap="butt"/><path d="M${xy(tail)}L${xy(pos)}" stroke="${active?'#63afca':'#adc2d0'}" stroke-width="25"/><circle cx="${fmt(pos[0])}" cy="${fmt(pos[1])}" r="18" fill="white" stroke="${color}" stroke-width="4"/><circle cx="${fmt(pos[0])}" cy="${fmt(pos[1])}" r="39" fill="transparent"/><path d="M${xy(pos)}L${xy(endArrow)}" stroke="${color}" stroke-width="2" marker-end="url(#port-arrow)"/><rect x="${fmt(pos[0]-28)}" y="${fmt(pos[1]-55)}" width="56" height="26" rx="13" fill="${active?'#246d8b':'white'}"/><text x="${fmt(pos[0])}" y="${fmt(pos[1]-37)}" text-anchor="middle" font-size="20" font-weight="bold" fill="${active?'white':'#34576f'}">${end.toUpperCase()} 口</text></g>`;}).join('');
 const fields=['run','roll','rise'],labels=['X 前後','Y 左右','Z 高低'];
 const chips=fields.map((key,i)=>`<g class="scene-dimension" data-dimension="${key}" role="button" tabindex="0" aria-label="修改 ${labels[i]}，目前 ${fmt(p[key])} 毫米"><rect x="${35+i*178}" y="286" width="164" height="57" rx="9" fill="white" stroke="#d5e1e8"/><rect x="${35+i*178}" y="298" width="3" height="31" rx="1.5" fill="${colors[i]}"/><text x="${49+i*178}" y="306" fill="#6a7d8a" font-size="15">${labels[i]}</text><text x="${49+i*178}" y="333" fill="#274052" font-size="24" font-weight="600">${fmt(p.layout==='planar'&&key==='roll'?0:p[key])}<tspan font-size="14" font-weight="400"> mm ✎</tspan></text></g>`).join('');
 return {frame,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 360" aria-label="兩管口量測互動示意" role="group"><defs><marker id="port-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#246d8b"/></marker></defs><g font-family="Arial,Microsoft JhengHei">${dims}${ports}${chips}<text x="570" y="24" text-anchor="end" fill="#8a9ca8" font-size="11">${esc(info.label)} · 量測示意</text></g></svg>`};
}
export function directionIcon(axis){const vector={'x+':[24,10],'x-':[-24,-10],'y+':[-24,10],'y-':[24,-10],'z+':[0,-26],'z-':[0,26]}[axis]??[24,-24],end=[38+vector[0],33+vector[1]],n=Math.hypot(...vector),back=end.map((v,i)=>v-vector[i]/n*8),normal=[-vector[1]/n*4,vector[0]/n*4];return `<svg viewBox="0 0 76 66" aria-hidden="true"><circle cx="38" cy="33" r="9" fill="#fff" stroke="currentColor" stroke-width="2"/><path d="M38 33L${xy(end)}M${xy(back.map((v,i)=>v+normal[i]))}L${xy(end)}L${xy(back.map((v,i)=>v-normal[i]))}" stroke="currentColor" stroke-width="2.5" fill="none"/></svg>`;}
export function elbowIcon(angle=90){const a=Math.max(1,Math.min(90,angle))*Math.PI/180,pts=Array.from({length:20},(_,i)=>[20+28*(1-Math.cos(a*i/19)),47-28*Math.sin(a*i/19)]);return `<svg viewBox="0 0 76 62" aria-hidden="true"><path d="${pts.map((q,i)=>(i?'L':'M')+xy(q)).join(' ')}" fill="none" stroke="currentColor" stroke-width="13"/><path d="M20 47v9" stroke="currentColor" stroke-width="13"/></svg>`;}
export function stockElbowSVG(p,end){const angle=p[end+'Kind']==='factory'?p[end+'FactoryAngle']:p[end+'Donor'],a=Math.max(1,Math.min(90,Number(angle)||90))*Math.PI/180,points=Array.from({length:31},(_,i)=>[70+102*(1-Math.cos(a*i/30)),157-102*Math.sin(a*i/30)]),path=points.map((q,i)=>(i?'L':'M')+xy(q)).join(' '),mid=[172-72,157-72];return `<svg viewBox="0 0 330 215" role="group" aria-label="手邊彎頭，點角度或半徑修改"><g font-family="Arial,Microsoft JhengHei"><path d="${path}" stroke="#42657c" stroke-width="32" fill="none"/><path d="${path}" stroke="#a9cbd9" stroke-width="27" fill="none"/><path d="M172 157H70M172 157L${xy(points.at(-1))}M172 157L${xy(mid)}" stroke="#6c97ad" stroke-width="1.5" stroke-dasharray="4 4" fill="none"/><circle cx="172" cy="157" r="3" fill="#6c97ad"/><g class="scene-dimension" data-supply-field="${end}${p[end+'Kind']==='factory'?'FactoryAngle':'Donor'}" role="button" tabindex="0" aria-label="修改原彎頭角度"><rect x="192" y="46" width="120" height="43" rx="8" fill="white" stroke="#d5e1e8"/><text x="204" y="74" fill="#246d8b" font-size="19">${fmt(angle)}° ✎</text></g>${p[end+'Kind']==='cut'?`<g class="scene-dimension" data-supply-field="${end}${p[end+'RadiusMethod']==='radius'?'Radius':'MeasuredArc'}" role="button" tabindex="0" aria-label="修改彎頭半徑或量測弧長"><rect x="191" y="104" width="120" height="49" rx="8" fill="white" stroke="#d5e1e8"/><text x="203" y="123" fill="#6a7d8a" font-size="11">${p[end+'RadiusMethod']==='radius'?'中心線 Rc':'完整'+(p[end+'RadiusMethod']==='outerArc'?'外背':'內腹')+'弧'}</text><text x="203" y="143" fill="#246d8b" font-size="16">${fmt(p[end+(p[end+'RadiusMethod']==='radius'?'Radius':'MeasuredArc')])} mm ✎</text></g>`:`<g class="scene-dimension" data-supply-field="${end}Takeout" role="button" tabindex="0" aria-label="修改中心至端面尺寸"><rect x="191" y="104" width="120" height="49" rx="8" fill="white" stroke="#d5e1e8"/><text x="203" y="123" fill="#6a7d8a" font-size="11">中心至端面 Ta</text><text x="203" y="143" fill="#246d8b" font-size="16">${fmt(p[end+'Takeout'])} mm ✎</text></g>`}<text x="24" y="199" fill="#71889b" font-size="11">原件尺寸示意 · 點尺寸修改</text></g></svg>`;}
export function weldSketchSVG(p){const joints=[{x:69,y:132,k:'aPortGap'},{x:141,y:113,k:'aGap'},{x:259,y:60,k:'bGap'},{x:329,y:42,k:'bPortGap'}];return `<svg viewBox="0 0 400 210" role="group" aria-label="四個焊口間隙，點 G1 到 G4 修改"><g fill="none" stroke-linejoin="round"><path d="M20 132H85Q104 132 122 120L278 51Q297 42 316 42H380" stroke="#34576f" stroke-width="22"/><path d="M20 132H85Q104 132 122 120L278 51Q297 42 316 42H380" stroke="#a9cbd9" stroke-width="17"/></g><g font-family="Arial,Microsoft JhengHei">${joints.map((j,i)=>`<g class="scene-dimension" data-gap="${j.k}" role="button" tabindex="0" aria-label="修改 G${i+1} 焊口間隙"><path d="M${j.x} ${j.y-12}v24" stroke="#f6f9fb" stroke-width="4"/><path d="M${j.x} ${j.y+13}v25" stroke="#b58039"/><circle cx="${j.x}" cy="${j.y+51}" r="16" fill="white" stroke="#b58039"/><text x="${j.x}" y="${j.y+56}" text-anchor="middle" font-size="12" fill="#94682e">G${i+1}</text><text x="${j.x}" y="${j.y+82}" text-anchor="middle" font-size="12" fill="#274052">${fmt(p[j.k])} mm</text></g>`).join('')}<text x="18" y="21" fill="#71889b" font-size="11">原兩彎頭接法 · 焊口位置示意</text></g></svg>`;}
